SELECT p.slug project,l.root_path,d.path,s.name,s.qualified_name,s.symbol_kind,s.line_number,d.freshness_status FROM code_symbols s JOIN source_documents d ON d.id=s.source_document_id JOIN repository_locations l ON l.id=d.repository_location_id JOIN projects p ON p.id=d.project_id WHERE p.slug=$1 AND d.is_current AND d.freshness_status='current' AND (s.name ILIKE ANY($2::text[]) OR s.qualified_name ILIKE ANY($2::text[])) AND ($3::text[] IS NULL OR EXISTS (SELECT 1 FROM unnest($3::text[]) AS allowed(root_path) WHERE l.root_path=allowed.root_path)) ORDER BY s.qualified_name LIMIT 40
